static int hex(const char *v){if(!v||strlen(v)!=64)return 0;for(size_t i=0;i<64;i++)if(!((v[i]>='0'&&v[i]<='9')||(v[i]>='a'&&v[i]<='f')))return 0;return 1;}
static int handle(const char *v){size_t n=v?strlen(v):0;if(n<23||n>127||memcmp(v,"tra:v1:",7))return 0;for(size_t i=7;i<n;i++)if(!((v[i]>='A'&&v[i]<='Z')||(v[i]>='a'&&v[i]<='z')||(v[i]>='0'&&v[i]<='9')||v[i]=='_'||v[i]==':'||v[i]=='-'))return 0;return 1;}
static int now_ms(uint64_t *value){struct timespec now;if(!value||clock_gettime(CLOCK_REALTIME,&now)<0)return-1;if(now.tv_sec<0||(uint64_t)now.tv_sec>UINT64_MAX/1000u){errno=EOVERFLOW;return-1;}*value=(uint64_t)now.tv_sec*1000u+(uint64_t)now.tv_nsec/1000000u;return 0;}
static int exact_command(const struct rtew_command_v4 *left,const struct rtew_command_v4 *right){char a[RTEW_V4_MAX_BYTES],b[RTEW_V4_MAX_BYTES];size_t an=0,bn=0;return rtew_encode_command_v4(left,a,sizeof(a),&an)==0&&rtew_encode_command_v4(right,b,sizeof(b),&bn)==0&&an==bn&&!memcmp(a,b,an);}
static int exact_handles(const struct rtdb_handle *actual,size_t count,const struct rtdb_command_admission *admission){if(!actual||!admission||count!=RTDB_HANDLE_COUNT||admission->enrolled_handle_count!=RTDB_HANDLE_COUNT)return 0;for(size_t i=0;i<RTDB_HANDLE_COUNT;i++){const struct rtdb_handle *a=&actual[i],*e=&admission->enrolled_handles[i];if(a->role!=(enum rtdb_handle_role)(i+1)||e->role!=(enum rtdb_handle_role)(i+1)||!handle(a->handle)||!handle(e->handle)||!hex(a->identity_sha256)||!hex(e->identity_sha256)||strcmp(a->handle,e->handle)||strcmp(a->identity_sha256,e->identity_sha256))return 0;for(size_t j=0;j<i;j++)if(!strcmp(a->handle,actual[j].handle)||!strcmp(e->handle,admission->enrolled_handles[j].handle)||!strcmp(a->identity_sha256,actual[j].identity_sha256)||!strcmp(e->identity_sha256,admission->enrolled_handles[j].identity_sha256))return 0;}return 1;}
static int command_cross_bound(const struct rtdb_context *context){const struct rtew_command_v4 *command=&context->admission.command;const struct rtca_admitted_use_context *use=context->credential_use;const struct rtca_context *owner=use?use->admitted_owner:NULL;const struct rtea_request *request=owner?&owner->request:NULL;const struct rtca_admission *credential=use?&use->admission:NULL;uint64_t current=0;if(!context->authority_session||!use||!owner||!request||!credential||now_ms(&current)<0)return 0;return current<command->deadline_unix_ms&&request->operation==RTEA_OPERATION_PREPARE&&context->authority_session->operation==RTEA_OPERATION_PREPARE&&!context->authority_session->readonly&&
    !strcmp(command->installation_id,request->installation_id)&&!strcmp(command->site_id,request->site_id)&&!strcmp(command->host_installation_id,request->host_installation_id)&&!strcmp(command->operation_id,request->operation_id)&&command->generation==request->generation&&!strcmp(command->target_handle,request->target_handle)&&!strcmp(command->acquired_request_sha256,request->request_sha256)&&
    !strcmp(command->operation_id,credential->operation_id)&&command->generation==credential->generation&&!strcmp(command->target_handle,credential->target_handle)&&!strcmp(command->credential_admission_receipt_sha256,credential->admission_receipt_sha256)&&!strcmp(command->credential_use_witness_sha256,use->witness_sha256)&&!strcmp(command->authority_instance_sha256,credential->authority_instance_sha256)&&
    !strcmp(command->authority_instance_sha256,context->authority_session->authority_instance_sha256)&&command->supervisor_generation==context->authority_session->supervisor_generation&&!strcmp(command->challenge_nonce,context->authority_session->challenge_nonce)&&command->deadline_unix_ms==owner->deadline_unix_ms&&!strcmp(command->asset_manifest_sha256,context->expected.asset_manifest_sha256);}
int rtdb_open_context(struct rtea_session *authority,struct rtca_admitted_use_context *credential,const struct rtdb_handle *handles,size_t count,const struct rtdb_command_admission *admission,const struct rtdo_expected *expected,struct rtdb_context *context){char encoded[RTEW_V4_MAX_BYTES];size_t encoded_size=0;if(!authority||!credential||!handles||!admission||!expected||!context||!exact_handles(handles,count,admission)||rtew_encode_command_v4(&admission->command,encoded,sizeof(encoded),&encoded_size)<0||strcmp(admission->command.asset_manifest_sha256,expected->asset_manifest_sha256)||rtea_validate_active_session(authority)<0||rtca_validate_admitted_use_context(credential)<0){errno=EACCES;return-1;}memset(context,0,sizeof(*context));context->authority_session=authority;context->credential_use=credential;context->expected=*expected;context->admission=*admission;memcpy(context->handles,handles,sizeof(context->handles));context->handle_count=count;if(rtdb_validate(context)<0){memset(context,0,sizeof(*context));errno=EACCES;return-1;}return 0;}
int rtdb_validate(struct rtdb_context *context){if(!context||context->closed||context->handle_count!=RTDB_HANDLE_COUNT||!exact_handles(context->handles,context->handle_count,&context->admission)||rtea_validate_active_session(context->authority_session)<0||rtca_validate_admitted_use_context(context->credential_use)<0||!command_cross_bound(context)){errno=ESTALE;return-1;}return 0;}
int rtdb_observe(struct rtdb_context *context,const struct rtew_command_v4 *command,struct rtew_inspection_v4 *inspection){if(rtdb_validate(context)<0||!command||!inspection)return-1;errno=ENOTSUP;return-1;}
#ifdef RECOVERY_TARGET_DOCKER_BACKEND_TESTING
static int observe_synthetic(struct rtdb_context *context,const struct rtew_command_v4 *command,const void *output,size_t size,struct rtew_inspection_v4 *inspection){if(rtdb_validate(context)<0||!command||!inspection)return-1;if(rtdo_parse_synthetic_daemon_transcript(output,size,command,&context->expected,inspection)<0)return-1;return rtdb_validate(context);}
static int run_fixed_probe(struct rtdb_context *context){int executable=open("/proc/self/exe",O_RDONLY|O_CLOEXEC);struct stat state;unsigned char elf[5];if(executable<0||fstat(executable,&state)<0||!S_ISREG(state.st_mode)||pread(executable,elf,sizeof(elf),0)!=(ssize_t)sizeof(elf)||memcmp(elf,"\x7f" "ELF",4)||elf[4]!=2){if(executable>=0)close(executable);errno=ENOEXEC;return-1;}pid_t child=fork();if(child<0){close(executable);return-1;}if(child==0){(void)setpgid(0,0);char *const argv[]={"darshan-recovery-fixed-docker-fixture","--fixed-backend-probe",NULL};char *const environment[]={"LANG=C","LC_ALL=C",NULL};syscall(SYS_execveat,executable,"",argv,environment,AT_EMPTY_PATH);_exit(126);}close(executable);context->child_pid=child;context->child_pgid=child;context->active=1;(void)setpgid(child,child);int status=0;pid_t joined;do joined=waitpid(child,&status,0);while(joined<0&&errno==EINTR);context->active=0;context->child_pid=context->child_pgid=0;if(joined!=child||!WIFEXITED(status)||WEXITSTATUS(status)!=0){errno=ECHILD;return-1;}if(kill(-child,0)==0||errno!=ESRCH){errno=EBUSY;return-1;}return 0;}
#endif
#ifdef RECOVERY_TARGET_DOCKER_BACKEND_TESTING
static int inspection_matches(const struct rtew_inspection_v4 *inspection,const struct rtew_command_v4 *command,const char semantic[65],const char wire[65]){return inspection&&command&&!strcmp(inspection->command_semantic_sha256,semantic)&&!strcmp(inspection->command_wire_sha256,wire)&&inspection->operation==command->operation&&inspection->role==command->role&&!strcmp(inspection->operation_id,command->operation_id)&&!strcmp(inspection->target_handle,command->target_handle)&&inspection->generation==command->generation&&!strcmp(inspection->command_nonce,command->command_nonce)&&!strcmp(inspection->authority_instance_sha256,command->authority_instance_sha256)&&inspection->supervisor_generation==command->supervisor_generation&&!strcmp(inspection->challenge_nonce,command->challenge_nonce)&&!strcmp(inspection->materialization_head_sha256,command->materialization_head_sha256)&&!strcmp(inspection->asset_manifest_sha256,command->asset_manifest_sha256);}
#endif
int rtdb_execute_fixed(struct rtdb_context *context,const void *wire,size_t size,const void *output,size_t output_size,struct rtew_inspection_v4 *inspection){if(rtdb_validate(context)<0)return-1;struct rtew_command_v4 command;if(rtew_parse_command_v4(wire,size,&command)<0||!exact_command(&command,&context->admission.command)){errno=EACCES;return-1;}
#ifndef RECOVERY_TARGET_DOCKER_BACKEND_TESTING
 (void)output;(void)output_size;(void)inspection;errno=ENOTSUP;return-1;
#else
 if(run_fixed_probe(context)<0||observe_synthetic(context,&command,output,output_size,inspection)<0)return-1;
 char semantic[65],wire_sha256[65],encoded[RTEW_V4_MAX_BYTES];size_t encoded_size=0;if(rtew_command_semantic_sha256_v4(&command,semantic)<0||rtew_command_wire_sha256_v4(wire,size,wire_sha256)<0)return-1;strcpy(inspection->command_wire_sha256,wire_sha256);if(!inspection_matches(inspection,&command,semantic,wire_sha256)||rtew_encode_inspection_v4(inspection,encoded,sizeof(encoded),&encoded_size)<0)return-1;
 return rtdb_validate(context);
#endif
}
int rtdb_cancel_join(struct rtdb_context *context){if(!context||context->closed){errno=EINVAL;return-1;}if(context->active&&context->child_pgid>0){(void)kill(-context->child_pgid,SIGTERM);(void)kill(-context->child_pgid,SIGKILL);int status;while(waitpid(context->child_pid,&status,0)<0&&errno==EINTR){}context->active=0;context->child_pid=context->child_pgid=0;}return rtdb_validate(context);}
int rtdb_close(struct rtdb_context *context){if(!context){errno=EINVAL;return-1;}if(context->active){errno=EBUSY;return-1;}memset(context,0,sizeof(*context));context->closed=1;return 0;}
